class Solution {
public:
    bool canConvertString(string s, string t, int k) {
        if (s.size() != t.size()) return false;
        int cnt[26] = {0};
        int n = (int)s.size();
        for (int i = 0; i < n; i++) {
            int r = ((t[i] - s[i]) % 26 + 26) % 26;
            if (r > 0) cnt[r]++;
        }
        for (int r = 1; r < 26; r++) {
            if (cnt[r] > 0) {
                long long needed = (long long)r + 26LL * (cnt[r] - 1);
                if (needed > k) return false;
            }
        }
        return true;
    }
};
